const FXRAW={"q":{"werkhof":{"giver":[-246.5,-34],"wall":[-262,-8],"drum":[-254,-8],"gate":[-253,30.8,-247,30.8],"lamps":[[-247,-22],[-247,6],[-247,36],[-262.5,-8]]},"markt":{"giver":[104,294],"zone":[110,300,122,309],"stalls":[[96,268],[110,268],[124,268],[138,268],[96,340],[110,340]],"fixed":[[130,372],[144,372]]},"soon":[[100,-390,"Alter Markt","Wie weit von der Wand?"],[-270,-322,"Nordpark","Abspannung vor dem Spiel"],[362,142,"Schloss Rheydt","Bonus-Auftrag"]],"closed":[-420,-163.2,"Verbindung zum Nordpark: öffnet mit einem späteren Auftrag"]},"talk":[{"x":-322,"y":-56.2,"name":"Mats","role":"wartet an der Haltestelle Schule Torfbend","say":["Neu hier? Am Werkhof gleich um die Ecke sucht unser Sportlehrer Herr Maaß jemanden, der rechnen kann.","Wenn das Tor am Werkhof offen wäre, käme man viel schneller zur Dohrer Straße. So muss man außen herum."]},{"x":-273.5,"y":-71.5,"name":"Herr Dittmann","role":"Lehrer, Klassenlehrer der 9c","say":["Willkommen an der GHS Dohr! Frau Ziemer und Herr Ballhorn suchen hinten auf dem Schulhof Hilfe beim Messen.","Merk dir: Die Hypotenuse liegt immer dem rechten Winkel gegenüber und ist die längste Seite.","Bevor du rechnest: Schätz kurz, ob das Ergebnis größer oder kleiner als die gegebenen Seiten sein muss."]},{"x":-305,"y":-132,"name":"Herr Jessen","role":"Lehrer, Pausenaufsicht","say":["Ich habe Pausenaufsicht. Rund um die Schule sind gelbe Dreiecks-Schilder versteckt. Eins hängt am Basketballkorb.","Suchst du eine Kathete? Dann rechne Hypotenuse² minus die andere Kathete² und zieh die Wurzel."]},{"x":-318,"y":-112,"name":"Frau Brand","role":"MPT-Team (multiprofessionelles Team)","say":["Hallo, ich bin Frau Brand vom MPT. Wenn eine Aufgabe nicht klappt, drück ruhig auf Tipp. Dafür ist er da.","Schritt für Schritt: erst quadrieren, dann addieren oder subtrahieren, zum Schluss die Wurzel."]},{"x":-265,"y":-104,"name":"Frau Colonna","role":"MPT-Team (multiprofessionelles Team)","say":["Hallo, ich bin Frau Colonna vom MPT. Hast du das Dreiecks-Schild am weißen Gartenhaus schon gefunden?","Im Auftragsheft siehst du jederzeit, was du schon geschafft hast und was noch fehlt."]},{"x":-283,"y":-121.5,"name":"Herr Aktas","role":"MPT-Team (multiprofessionelles Team)","say":["Ich bin Herr Aktas vom MPT. Unter der Außentreppe hängt übrigens auch ein Dreiecks-Schild.","Quer über den Hof ist kürzer als am Zaun entlang. Wie viel kürzer, kannst du mit Pythagoras ausrechnen."]},{"x":-160,"y":8,"name":"Elif","role":"auf dem Spielplatz","say":["Quer über die Wiese ist kürzer als außen herum. Warum eigentlich? Frag mal den Park-Kurier.","Zum Rheydter Markt? Immer die Dohrer Straße runter und dann rechts in die Gartenstraße."]},{"x":136,"y":350,"name":"Herr Brands","role":"Markthändler","say":["Frische Äpfel vom Niederrhein! Wenn Frau Krahe mit ihrer Klasse die neuen Stände aufbaut, wird es hier richtig voll.","Vom Rathaus bis zur Hauptkirche sind es nur ein paar Schritte. Aber diagonal über den Platz ist noch kürzer."]},{"x":92,"y":-372,"name":"Frau Okafor","role":"Stadtführerin","say":["Der Turm da drüben gehört zum Münster St. Vitus. Den sieht man von fast überall in der Innenstadt.","Die Hindenburgstraße führt vom Alten Markt hinunter zum Hauptbahnhof."]},{"x":-268,"y":-338,"name":"Tarik","role":"Platzwart","say":["Heute ist kein Spiel. Aber bald bauen wir hier ein Veranstaltungszelt auf, dafür brauchen wir noch jemanden zum Rechnen."]}],"school":{"label":"GHS Dohr · Standort Torfbend","v":2},"bld":[{"p":[-292,-41,-254.5,-41,-254.5,-39.4,-292,-39.4],"h":3,"m":0,"t":"wall","c":"#9a9388","k":"plain"},{"p":[-245.5,-41,-213,-41,-213,-39.4,-245.5,-39.4],"h":3,"m":0,"t":"wall","c":"#9a9388","k":"plain"},{"p":[-292,30,-253,30,-253,31.6,-292,31.6],"h":3,"m":0,"t":"wall","c":"#9a9388","k":"plain"},{"p":[-247,30,-213,30,-213,31.6,-247,31.6],"h":3,"m":0,"t":"wall","c":"#9a9388","k":"plain"},{"p":[-292,-41,-290.4,-41,-290.4,31.6,-292,31.6],"h":3,"m":0,"t":"wall","c":"#9a9388","k":"plain"},{"p":[-214.6,-41,-213,-41,-213,31.6,-214.6,31.6],"h":3,"m":0,"t":"wall","c":"#9a9388","k":"plain"},{"p":[-288,-32,-262,-32,-262,12,-288,12],"h":8,"m":0,"t":"industrial","n":"Werkhof Dohr","c":"#c9c6bf","k":"plain","rc":"#5e6064"},{"p":[-238,-4,-220,-4,-220,22,-238,22],"h":4.5,"m":0,"t":"industrial","c":"#b9b4a8","k":"plain","rc":"#6b6d70"},{"p":[-332,-84,-318,-84,-318,-66,-332,-66],"h":16,"m":0,"t":"school","x":1},{"p":[-318,-82,-293,-82,-293,-70,-318,-70],"h":12.4,"m":0,"t":"school","x":1},{"p":[-293,-90,-279,-90,-279,-67,-293,-67],"h":16.5,"m":0,"t":"school","x":1},{"p":[-279,-90,-268,-90,-268,-80,-279,-80],"h":11.2,"m":0,"t":"school","x":1},{"p":[-276.6,-80,-270.4,-80,-270.4,-77,-276.6,-77],"h":5.4,"m":0,"t":"school","x":1},{"p":[-296,-106,-268,-106,-268,-90,-296,-90],"h":7.9,"m":0,"t":"school","x":1},{"p":[-295.3,-111.6,-286.5,-111.6,-286.5,-109.8,-295.3,-109.8],"h":3.9,"m":0,"t":"stairs","x":1},{"p":[-292,-132,-266,-132,-266,-125,-292,-125],"h":3.9,"m":0,"t":"school","x":1},{"p":[-290,-148,-268,-148,-268,-132,-290,-132],"h":8.3,"m":0,"t":"school","x":1},{"p":[-270,-133.4,-269.2,-133.4,-269.2,-132.6,-270,-132.6],"h":10.6,"m":0,"t":"chimney","x":1},{"p":[-258,-82,-245,-82,-245,-66,-258,-66],"h":13,"m":0,"t":"house","x":1},{"p":[-334,-63.8,-276.5,-63.8,-276.5,-63.4,-334,-63.4],"h":1.9,"m":0,"t":"wall","x":1},{"p":[-276.5,-63.9,-275.9,-63.9,-275.9,-63.3,-276.5,-63.3],"h":2.9,"m":0,"t":"wall","x":1},{"p":[-271.3,-63.9,-270.7,-63.9,-270.7,-63.3,-271.3,-63.3],"h":2.9,"m":0,"t":"wall","x":1},{"p":[-265.6,-63.9,-265,-63.9,-265,-63.3,-265.6,-63.3],"h":2.9,"m":0,"t":"wall","x":1},{"p":[-265,-63.8,-261.2,-63.8,-261.2,-63.4,-265,-63.4],"h":1.8,"m":0,"t":"wall","x":1},{"p":[-261.8,-149.8,-261.2,-149.8,-261.2,-63.4,-261.8,-63.4],"h":2.4,"m":0,"t":"wall","x":1},{"p":[-334.2,-149.8,-334,-149.8,-334,-63.8,-334.2,-63.8],"h":2,"m":0,"t":"fence","c":"#5d646b","k":"fence"},{"p":[-334,-150,-261.8,-150,-261.8,-149.8,-334,-149.8],"h":2,"m":0,"t":"fence","c":"#5d646b","k":"fence"}],"areas":[{"t":"plaza","p":[-290.4,-39.4,-214.6,-39.4,-214.6,30,-290.4,30]},{"t":"yard","p":[-334,-149.8,-261.5,-149.8,-261.5,-63.4,-334,-63.4],"n":"Schulhof"}]};
/* ================= Spielinhalte auf der echten Karte =================
   Die Missionen, Figuren und das Schulmodell stammen aus der früheren verdichteten Spielkarte.
   Hier werden sie auf echte Orte in Rheydt und Mülfort gesetzt:
   - Schule (Cluster S): Schulmodell und Schulhof auf das Grundstück Am Torfbend, gedreht wie die Straße.
   - Werkhof (Cluster W): auf die freie Fläche südwestlich der Schule, zwischen Am Torfbend und den Kleingärten.
   - Markt (Cluster M): Marktstände und Markt-Auftrag auf den Rheydter Markt (Abstände der Stände um 40 % verkürzt,
     die vermessene Zone behält ihre Größe 12 m × 9 m).
   - Alle anderen Orte stehen unten mit echten Koordinaten und werden auf den nächsten freien Gehweg geschoben.
   FXRAW enthält die Rohdaten der früheren Spielkarte (Koordinaten der Spielkarte). */
(function(){
const F=FXRAW;
const XF=[{id:"S",b:[-346,-244,-155,-44],f:[-261.5,-63.4],t:[893.1,240.9],r:.1923},
          {id:"W",b:[-293,-212,-44,40],f:[-252.5,-5],t:[790,282],r:0},
          {id:"M",b:[85,190,255,380],f:[137.5,320],t:[-540,-805],r:0,s:.6}];
const clu=(x,y)=>XF.find(c=>x>=c.b[0]&&x<=c.b[1]&&y>=c.b[2]&&y<=c.b[3]);
function FX(x,y){const c=clu(x,y);if(!c)return [x,y];const s=c.s||1,dx=(x-c.f[0])*s,dy=(y-c.f[1])*s,co=Math.cos(c.r),si=Math.sin(c.r);
  return [+(c.t[0]+dx*co-dy*si).toFixed(2),+(c.t[1]+dx*si+dy*co).toFixed(2)]}
const tp=p=>{const o=[];for(let i=0;i<p.length;i+=2)o.push(...FX(p[i],p[i+1]));return o};
const pip=(p,x,y)=>{let c=false;for(let i=0,j=p.length-2;i<p.length;j=i,i+=2){const xi=p[i],yi=p[i+1],xj=p[j],yj=p[j+1];if(((yi>y)!=(yj>y))&&(x<(xj-xi)*(y-yi)/(yj-yi)+xi))c=!c}return c};
MG.FX=FX;MG.XF=XF;MG.FXC=clu;

/* ---- Gebäude: Schule und Werkhof einsetzen, überlappende OSM-Gebäude an dieser Stelle entfernen ---- */
const yard=F.areas.find(a=>a.t==="yard").p, wk=[-293,-42,-212,-42,-212,32,-293,32];
const clear=[tp(yard),tp(wk)];
const hit=p=>{for(const c of clear){for(let i=0;i<p.length;i+=2)if(pip(c,p[i],p[i+1]))return true;for(let i=0;i<c.length;i+=2)if(pip(p,c[i],c[i+1]))return true}return false};
const before=MG.buildings.length;MG.buildings=MG.buildings.filter(b=>!hit(b.p));
MG.fxRemoved=before-MG.buildings.length;
for(const b of F.bld)MG.buildings.push(Object.assign({},b,{p:tp(b.p),fx:1}));
for(const a of F.areas)MG.areas.push(Object.assign({},a,{p:tp(a.p)}));
MG.schools=MG.schools.filter(s=>!/Auslagerung \(Sekundarstufe I\)/.test(s.n));
MG.schools.push({n:"GHS Dohr · Standort Torfbend",p:tp(yard)});
MG.school=F.school;

/* ---- freie Stelle auf dem Gehweg suchen (nicht im Gebäude, nicht auf der Fahrbahn) ---- */
const N=MG.nodes,CAR=/^(primary|secondary|tertiary|residential|unclassified|service|living_street|trunk)/;
function free(x,y){const B=MG.buildings.filter(b=>{for(let i=0;i<b.p.length;i+=2)if(Math.abs(b.p[i]-x)<60&&Math.abs(b.p[i+1]-y)<60)return true;return false});
  const R=MG.roads.filter(r=>CAR.test(r.h)&&r.i.some(i=>Math.abs(N[2*i]-x)<400&&Math.abs(N[2*i+1]-y)<400));
  const ok=(px,py)=>{if(B.some(b=>pip(b.p,px,py)))return false;
    for(const r of R)for(let k=1;k<r.i.length;k++){const a=r.i[k-1],b=r.i[k],ax=N[2*a],ay=N[2*a+1],dx=N[2*b]-ax,dy=N[2*b+1]-ay,
      t=Math.max(0,Math.min(1,((px-ax)*dx+(py-ay)*dy)/(dx*dx+dy*dy||1)));if(Math.hypot(ax+t*dx-px,ay+t*dy-py)<(r.w||6)/2+1.5)return false}return true};
  for(let rr=0;rr<40;rr+=.75){const n=Math.max(1,Math.round(rr*4));for(let k=0;k<n;k++){const a=k/n*Math.PI*2,px=x+Math.cos(a)*rr,py=y+Math.sin(a)*rr;if(ok(px,py))return [+px.toFixed(2),+py.toFixed(2)]}}
  return [x,y]}
MG.fxFree=free;

/* ---- Aufträge ---- */
const q=JSON.parse(JSON.stringify(F.q)),w=q.werkhof,m=q.markt;
for(const k of ["giver","wall","drum"])w[k]=FX(...w[k]);
{const a=FX(w.gate[0],w.gate[1]),b=FX(w.gate[2],w.gate[3]);w.gate=[a[0],a[1],b[0],b[1]]}
w.lamps=w.lamps.map(l=>FX(...l));
{const z=m.zone,c=FX((z[0]+z[2])/2,(z[1]+z[3])/2),hw=(z[2]-z[0])/2,hh=(z[3]-z[1])/2;m.zone=[+(c[0]-hw).toFixed(2),+(c[1]-hh).toFixed(2),+(c[0]+hw).toFixed(2),+(c[1]+hh).toFixed(2)]}
m.giver=FX(...m.giver);m.stalls=m.stalls.map(s=>FX(...s));m.fixed=m.fixed.map(s=>FX(...s));
const O=MG.real.orte;
q.soon=[[O.gladbach_hbf.x,O.gladbach_hbf.y,"Alter Markt (Phase 3)","Wie weit von der Wand?"],[O.borussia_park.x,O.borussia_park.y,"Nordpark (Phase 5)","Abspannung vor dem Spiel"],[O.schloss_rheydt.x,O.schloss_rheydt.y,"Schloss Rheydt (Phase 2)","Bonus-Auftrag"]];
delete q.closed;MG.q=q;

/* ---- Auftraggeber an echten Orten ---- */
MG.givers={
  fire:[...free(-452,-822),"Einsatzleitung an der Hauptkirche Rheydt"],
  tv:[...free(-432,-905),"Elektromarkt an der Hauptstraße"],
  taxi:[...free(-872,-250),"Taxistand am Rheydter Hauptbahnhof"],
  amt:[...free(-497,-762),"Rathaus Rheydt"],
  park:[...free(595,640),"Grünanlage in Mülfort"],
  crane:[...free(382,330),"Trainingsgelände am Mülforter Bruch"],
  heli:[...free(382,470),"Übungswiese im Mülforter Bruch"],
  shop:[...free(-390,-962),"Gartenstraße"]};

/* ---- Menschen zum Ansprechen ---- */
const RT=s=>s.replace(/zur Dohrer Straße/g,"zu den Kleingärten").replace(/Dohrer Straße/g,"Straße an den Kleingärten").replace(/Nordpark/g,"Mülforter Bruch");
const OVR={Elif:{at:[600,612],role:"in der Grünanlage",say:["Quer über die Wiese ist kürzer als außen herum. Warum eigentlich? Frag mal den Park-Kurier.","Zum Rheydter Markt? Am schnellsten mit dem Taxi oder mit dem Rad über die Hauptstraße."]},
  "Frau Okafor":{at:[-458,-812],say:["Der Turm da drüben gehört zur Evangelischen Hauptkirche Rheydt. Den sieht man schon von der Hauptstraße aus.","Vom Markt zum Rathaus sind es nur ein paar Schritte. Diagonal über den Platz ist es noch kürzer."]},
  Tarik:{at:[388,400],role:"Platzwart im Mülforter Bruch"},
  Mats:{say:["Neu hier? Am Werkhof gleich um die Ecke sucht unser Hausmeister Herr Ballhorn jemanden, der rechnen kann.","Herr Maaß, unser Sportlehrer, ist meistens in der Sporthalle hinten auf dem Schulhof."]},
  "Herr Dittmann":{role:"Klassenlehrer der 9c",say:["Willkommen an der GHS Dohr! Frau Ziemer, Klassenlehrerin der 9a, und Herr Jessen suchen hinten auf dem Schulhof Hilfe beim Messen.","Merk dir: Die Hypotenuse liegt immer dem rechten Winkel gegenüber und ist die längste Seite."]}};
MG.talk=F.talk.filter(t=>t.name!=="Herr Jessen").map(t=>{const o=OVR[t.name]||{},r=Object.assign({},t,o);const p=o.at?free(...o.at):FX(t.x,t.y);r.x=p[0];r.y=p[1];delete r.at;r.say=r.say.map(RT);r.role=RT(r.role);return r});
/* Frau Costantino: Lehrerin und Verkehrsbeauftragte, am Gehweg vor dem Schuleingang */
{const p=free(...FX(-304,-58.6));MG.talk.push({x:p[0],y:p[1],name:"Frau Costantino",role:"Englischlehrerin · Verkehrsbeauftragte der GHS Dohr",shirt:"#b03060",
  say:["Hello! I'm Mrs Costantino, your English teacher. (Ich bin Frau Costantino, eure Englischlehrerin.) Ask me for an English task!","Traffic lights: wait for green – even if there is no car. (An der Ampel erst bei Grün gehen.)","The hypotenuse is the longest side of a right-angled triangle. (Die Hypotenuse ist die längste Seite.)"]})}
MG.parked=[];MG.signs=[];MG.zebra=[];MG.decals=[];
MG.spielkarte=false;
})();
